WITH flattened_attrs AS (SELECT id, service, level, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version FROM app_logs WHERE service IN ('billing', 'search', 'checkout')) SELECT CASE WHEN retry_count >= 3 THEN 'PREMIUM' ELSE 'STANDARD' END AS retry_count_tier, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(retry_count, 0.95) AS retry_count_p95, AVG(duration_sec) FILTER (WHERE level = 'DEBUG') AS debug_avg_duration_sec, SUM(retry_count) FILTER (WHERE level = 'DEBUG') AS debug_total_retry_count FROM flattened_attrs GROUP BY retry_count_tier ORDER BY debug_avg_duration_sec DESC NULLS LAST;
